window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64cf6b473386c4b8"]={"versions": [{"id": "FIG-64cf6b473386c4b8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager (Steuerung des Abschaltablaufs)</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an BswM mit Rückkehrantwort</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an SchM mit Rückkehrantwort</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf an EcuM zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Lokaler synchroner Aufruf an EcuM zur Festlegung des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum Herunterfahren des Betriebssystems</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf, woraufhin die Ausführungsaktivierung an <code>BswM</code> übergeht und nach Abschluss der Deinitialisierung an <code>EcuM</code> zurückkehrt.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf; die Aktivierung geht temporär an <code>SchM</code> über und kehrt mit Deinitialisierungsabschluss an <code>EcuM</code> zurück.</li>\n<li><code>EcuM</code> führt einen lokalen Selbstaufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus, um anhängige Weckereignisse zu ermitteln.</li>\n<li>Optionales Fragment <code>opt</code> mit der Bedingung <code>Pending wakeup events?</code>: Falls anhängige Weckereignisse vorliegen, ruft <code>EcuM</code> sich selbst mit <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code> auf, um das Shutdown-Target anzupassen.</li>\n<li><code>EcuM</code> ruft synchron <code>ShutdownOS()</code> auf der Lebenslinie <code>Os</code> auf, wodurch der OS-Shutdown initiiert wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Vorgabe für die Reihenfolge der Deinitialisierungsschritte vor <code>ShutdownOS()</code>. BswM muss vor SchM deinitialisiert werden. Vor dem Herunterfahren des OS müssen anhängige Weckereignisse geprüft werden; liegen solche vor, ist das Shutdown-Target programmatisch neu auszuwählen, bevor <code>ShutdownOS()</code> aufgerufen wird.</p>"}, {"id": "FIG-2745e1ac1707ec4a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf von EcuM an den Integration Code mit Rückkehrantwort</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an BswM mit Rückkehrantwort</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an SchM mit Rückkehrantwort</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf an EcuM zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Lokaler synchroner Aufruf an EcuM zur Festlegung des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum Herunterfahren des Betriebssystems</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron den Callout <code>EcuM_OnGoOffOne()</code> auf der Lebenslinie <code>Integration Code</code> auf, wodurch anwenderspezifische Vorbereitungen vor dem Abschalten ausgeführt werden, und wartet auf die Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf; die Aktivierung geht an <code>BswM</code> und kehrt nach erfolgter Deinitialisierung an <code>EcuM</code> zurück.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf; nach Ausführung in <code>SchM</code> kehrt der Kontrollfluss an <code>EcuM</code> zurück.</li>\n<li><code>EcuM</code> führt den lokalen Aufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus, um zu prüfen, ob Weckereignisse anstehen.</li>\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Wurden anstehende Weckereignisse erkannt, setzt <code>EcuM</code> via internem Aufruf <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code> ein neues Abschalzziel.</li>\n<li><code>EcuM</code> ruft <code>ShutdownOS()</code> an der Lebenslinie <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Vor der Deinitialisierung von BSW-Modulen muss der Integrations-Callout <code>EcuM_OnGoOffOne()</code> ausgeführt werden, um Integratoren Hooks für Shutdown-Aktivitäten einzuräumen. Nachfolgend gelten die strikten Deinitialisierungsaufrufe für BswM und SchM sowie die Prüfung anstehender Weckereignisse vor dem endgültigen <code>ShutdownOS()</code>.</p>"}, {"id": "FIG-dd22f204c6ffbfd4", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf von EcuM an Integration Code mit Rückkehrantwort</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an BswM mit Rückkehrantwort</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an SchM mit Rückkehrantwort</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf an EcuM zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf an EcuM zur Festlegung des Abschalzziels mit typisierten Parametern</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum Herunterfahren des Betriebssystems</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf dessen Rückkehr.</li>\n<li><code>EcuM</code> deinitialisiert synchron <code>BswM</code> mittels <code>BswM_Deinit()</code>.</li>\n<li><code>EcuM</code> deinitialisiert synchron <code>SchM</code> mittels <code>SchM_Deinit()</code>.</li>\n<li><code>EcuM</code> ruft intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> auf.</li>\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei anstehenden Weckereignissen erfolgt der interne Aufruf <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>.</li>\n<li>Abschließend ruft <code>EcuM</code> synchron <code>ShutdownOS()</code> auf der Lebenslinie <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstelle zur Festlegung des Abschalzziels <code>EcuM_SelectShutdownTarget</code> verwendet strikt die Typen <code>EcuM_ShutdownTargetType</code> und <code>EcuM_ShutdownModeType</code>. Der Ablauf erzwingt die Reihenfolge: <code>EcuM_OnGoOffOne()</code>, BswM-Deinitialisierung, SchM-Deinitialisierung, Weckereignisabfrage mit möglicher Zielanpassung und Aufruf von <code>ShutdownOS()</code>.</p>"}, {"id": "FIG-d01ed5b15c17c1da", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf von EcuM an Integration Code mit Rückkehrantwort</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an BswM mit Rückkehrantwort</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf von EcuM an SchM mit Rückkehrantwort</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf an EcuM zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf an EcuM zur Festlegung des Abschalzziels mit typisierten Parametern</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum Herunterfahren des Betriebssystems</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf dessen Rückkehr.</li>\n<li><code>EcuM</code> deinitialisiert synchron <code>BswM</code> mittels <code>BswM_Deinit()</code>.</li>\n<li><code>EcuM</code> deinitialisiert synchron <code>SchM</code> mittels <code>SchM_Deinit()</code>.</li>\n<li><code>EcuM</code> ruft intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> auf.</li>\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei anstehenden Weckereignissen erfolgt der interne Aufruf <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>.</li>\n<li>Abschließend ruft <code>EcuM</code> synchron <code>ShutdownOS()</code> auf der Lebenslinie <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstelle zur Festlegung des Abschalzziels <code>EcuM_SelectShutdownTarget</code> verwendet strikt die Typen <code>EcuM_ShutdownTargetType</code> und <code>EcuM_ShutdownModeType</code>. Der Ablauf erzwingt die Reihenfolge: <code>EcuM_OnGoOffOne()</code>, BswM-Deinitialisierung, SchM-Deinitialisierung, Weckereignisabfrage mit möglicher Zielanpassung und Aufruf von <code>ShutdownOS()</code>.</p>"}, {"id": "FIG-bc759c6da1d76cbb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf an Integration Code</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an BswM</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an SchM</li>\n<li><code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage validierter Weckereignisse</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf zur Neuauswahl des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum OS-Shutdown</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li>Alternativ-Fragment <code>alt</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei vorliegenden Weckereignissen ruft <code>EcuM</code> intern <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code> auf.</li>\n<li><code>EcuM</code> ruft synchron <code>ShutdownOS()</code> auf <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Einführung des Konfigurationsparameters <code>EcuMIgnoreWakeupEvValOffPreOS</code>. Abhängig von diesem Parameter muss die Implementierung entweder bereits validierte Weckereignisse (<code>EcuM_GetValidatedWakeupEvents</code>) oder noch anstehende/unvalidierte Weckereignisse (<code>EcuM_GetPendingWakeupEvents</code>) vor dem Eintreten in das optionale Fragment zur Zielneuauswahl abfragen.</p>"}, {"id": "FIG-d49bd5ca41703c08", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf an Integration Code</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an BswM</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an SchM</li>\n<li><code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage validierter Weckereignisse</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf zur Neuauswahl des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum OS-Shutdown</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li>Alternativ-Fragment <code>alt</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei vorliegenden Weckereignissen ruft <code>EcuM</code> intern <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code> auf.</li>\n<li><code>EcuM</code> ruft synchron <code>ShutdownOS()</code> auf <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Einführung des Konfigurationsparameters <code>EcuMIgnoreWakeupEvValOffPreOS</code>. Abhängig von diesem Parameter muss die Implementierung entweder bereits validierte Weckereignisse (<code>EcuM_GetValidatedWakeupEvents</code>) oder noch anstehende/unvalidierte Weckereignisse (<code>EcuM_GetPendingWakeupEvents</code>) vor dem Eintreten in das optionale Fragment zur Zielneuauswahl abfragen.</p>"}, {"id": "FIG-699ac71b7db84495", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf an Integration Code</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an BswM</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an SchM</li>\n<li><code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage validierter Weckereignisse</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf zur Neuauswahl des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum OS-Shutdown</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li>Alternativ-Fragment <code>alt</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei vorliegenden Weckereignissen ruft <code>EcuM</code> intern <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code> auf.</li>\n<li><code>EcuM</code> ruft synchron <code>ShutdownOS()</code> auf <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Einführung des Konfigurationsparameters <code>EcuMIgnoreWakeupEvValOffPreOS</code>. Abhängig von diesem Parameter muss die Implementierung entweder bereits validierte Weckereignisse (<code>EcuM_GetValidatedWakeupEvents</code>) oder noch anstehende/unvalidierte Weckereignisse (<code>EcuM_GetPendingWakeupEvents</code>) vor dem Eintreten in das optionale Fragment zur Zielneuauswahl abfragen.</p>"}, {"id": "FIG-066c829b22defe94", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des standardisierten Ablaufs der Phase <code>OffPreOS</code> innerhalb des AUTOSAR Basic Software Moduls ECU State Manager (<code>EcuM</code>, Classic Platform). Das Diagramm beschreibt die geordnete Deinitialisierung grundlegender Systemkomponenten vor der Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager</li>\n<li><code>Integration Code</code>: Integrationsspezifischer Callback-/Callout-Code</li>\n<li><code>«module» BswM</code>: Basic Software Mode Manager</li>\n<li><code>«module» SchM</code>: Basic Software Scheduler Module</li>\n<li><code>«module» Os</code>: Operating System</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_OnGoOffOne()</code>: Synchroner Callout-Aufruf an Integration Code</li>\n<li><code>BswM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an BswM</li>\n<li><code>SchM_Deinit()</code>: Synchroner Deinitialisierungsaufruf an SchM</li>\n<li><code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage validierter Weckereignisse</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Lokaler synchroner Aufruf zur Abfrage anstehender Weckereignisse</li>\n<li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>: Lokaler synchroner Aufruf zur Neuauswahl des Abschalzziels</li>\n<li><code>ShutdownOS()</code>: Synchroner Aufruf an Os zum OS-Shutdown</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequentieller Ablauf:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> ruft synchron <code>EcuM_OnGoOffOne()</code> am <code>Integration Code</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>BswM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li><code>EcuM</code> ruft synchron <code>SchM_Deinit()</code> auf und wartet auf Rückkehr.</li>\n<li>Alternativ-Fragment <code>alt</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n<li>Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code>: <code>EcuM</code> führt intern <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Optionales Fragment <code>opt Pending wakeup events?</code>: Bei vorliegenden Weckereignissen ruft <code>EcuM</code> intern <code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code> auf.</li>\n<li><code>EcuM</code> ruft synchron <code>ShutdownOS()</code> auf <code>Os</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Einführung des Konfigurationsparameters <code>EcuMIgnoreWakeupEvValOffPreOS</code>. Abhängig von diesem Parameter muss die Implementierung entweder bereits validierte Weckereignisse (<code>EcuM_GetValidatedWakeupEvents</code>) oder noch anstehende/unvalidierte Weckereignisse (<code>EcuM_GetPendingWakeupEvents</code>) vor dem Eintreten in das optionale Fragment zur Zielneuauswahl abfragen.</p>"}], "trans": [{"from": "FIG-64cf6b473386c4b8", "to": "FIG-2745e1ac1707ec4a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Lebenslinie <code>Integration Code</code> ergänzt.</li>\n<li>Synchroner Aufruf von <code>EcuM_OnGoOffOne()</code> an <code>Integration Code</code> zu Beginn der Sequenz eingefügt.</li>\n</ul>"}, {"from": "FIG-2745e1ac1707ec4a", "to": "FIG-dd22f204c6ffbfd4", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameterliste von <code>EcuM_SelectShutdownTarget()</code> geändert von <code>(Std_ReturnType, EcuM_StateType, uint8)</code> zu <code>(Std_ReturnType, EcuM_ShutdownTargetType, EcuM_ShutdownModeType)</code>.</li>\n</ul>"}, {"from": "FIG-dd22f204c6ffbfd4", "to": "FIG-d01ed5b15c17c1da", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d01ed5b15c17c1da", "to": "FIG-bc759c6da1d76cbb", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kombiniertes Fragment <code>alt</code> zur Auswertung der Wakeup-Events vor dem Shutdown-Target-Block eingefügt.</li>\n<li>Erster Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code> mit lokalem Aufruf <code>EcuM_GetValidatedWakeupEvents(EcuM_WakeupSourceType)</code>.</li>\n<li>Zweiter Zweig <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code> mit lokalem Aufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>.</li>\n</ul>"}, {"from": "FIG-bc759c6da1d76cbb", "to": "FIG-d49bd5ca41703c08", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d49bd5ca41703c08", "to": "FIG-699ac71b7db84495", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textbeschneidung/Layout-Verschiebung an den linken Rahmenbeschriftungen: Die Bezeichner <code>[EcuMIgnoreWakeupEvValOffPreOS is TRUE]</code>, <code>[EcuMIgnoreWakeupEvValOffPreOS is FALSE]</code> und <code>opt Pending wakeup events?</code> ragen geringfügig über die linke Lebenslinie bzw. den Fragmentrahmen hinaus.</li>\n</ul>"}, {"from": "FIG-699ac71b7db84495", "to": "FIG-066c829b22defe94", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
